/* Animated pool water + waterfall for the hero photo (hero-pavilion-pool-hd.webp).
   Masks are drawn for that exact photo: if the photo changes, remove this script. */
(function(){
  const img=document.querySelector('.hero-img img');
  if(!img||!/hero-pavilion-pool-hd/.test(img.src)||matchMedia('(prefers-reduced-motion:reduce)').matches) return;
  const IW=1662,IH=928,X0=400,Y0=580,CW=1262,CH=290;
  const cv=document.createElement('canvas');
  cv.id='heroWater';
  cv.setAttribute('aria-hidden','true');
  cv.style.cssText='position:absolute;pointer-events:none;opacity:0;transition:opacity 1s';
  const gl=cv.getContext('webgl',{premultipliedAlpha:true,alpha:true,antialias:false});
  if(!gl) return;
  const VS='attribute vec2 p;varying vec2 u;void main(){u=vec2(p.x*.5+.5,.5-p.y*.5);gl_Position=vec4(p,0.,1.);}';
  const FS=`
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
varying vec2 u;uniform sampler2D im,mk;uniform float t;
float h(vec2 p){p=mod(p,289.);vec3 q=fract(vec3(p.xyx)*.1031);q+=dot(q,q.yzx+33.33);return fract((q.x+q.y)*q.z);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y)-.5;}
float wave(vec2 P){return n(P+vec2(t*.5,t*1.1))+n(P*1.9+vec2(-t*.9,t*1.4)+7.)*.6+n(P*3.7+vec2(t*1.3,-t*1.2)+19.)*.3;}
void main(){
  vec2 px=vec2(400.,580.)+u*vec2(1262.,290.);
  vec2 sz=vec2(1262.,290.);
  vec3 m=texture2D(mk,u).rgb;
  float a=max(m.r,max(m.g,m.b));
  if(a<.01){gl_FragColor=vec4(0.);return;}
  vec3 c=texture2D(im,u).rgb;
  // pool: ripples in perspective, smaller toward the far edge
  float H=max(px.y-560.,70.);
  vec2 P=vec2((px.x-830.)/H*9.,4200./H);
  float w=wave(P),wx=wave(P+vec2(.35,0.))-w,wz=wave(P+vec2(0.,.35))-w;
  // rings spreading from the foot of the waterfall
  vec2 d=vec2((px.x-1035.)/58.,(px.y-656.)/20.);
  float r=length(vec2(max(abs(d.x)-.8,0.),d.y));
  float ring=sin(r*9.-t*6.)*exp(-r*.75);
  float near=clamp((px.y-640.)/210.,0.,1.);
  vec2 off=vec2(wx*mix(5.,15.,near),wz*mix(3.,9.,near)+ring*1.6)/sz;
  vec2 q=u+off*smoothstep(.2,.9,texture2D(mk,u+off).r)*m.r;
  vec3 pool=texture2D(im,q).rgb;
  pool*=1.+wz*.22+ring*.09;
  pool+=vec3(.55,.75,.85)*smoothstep(.16,.42,wz+w*.22)*.13;
  // waterfall: streaks running down the sheet
  float v=clamp((px.y-594.)/62.,0.,1.);
  float L=996.-11.*sqrt(v),R=1104.-23.*sqrt(v);
  float s=(px.x-L)/(R-L);
  float fl=sqrt(v+.03);
  vec2 fo=vec2(n(vec2(s*26.,fl*5.-t*5.))*2.4,n(vec2(s*34.,fl*4.-t*4.5)+31.)*9.)/sz;
  vec3 fall=texture2D(im,u+fo*texture2D(mk,u+fo).g).rgb;
  float st=n(vec2(s*46.,fl*4.5-t*6.))+n(vec2(s*95.,fl*7.-t*8.)+11.)*.7;
  fall=fall*(1.+st*.5)+vec3(.8,.9,1.)*max(st,0.)*.26;
  // foam where it lands
  float fm=n(vec2(px.x*.16,px.y*.35-t*3.))+n(vec2(px.x*.33+t*1.5,px.y*.6+t*4.))*.7;
  c=mix(c,pool,m.r);
  c=mix(c,fall,m.g);
  c+=vec3(.85,.93,1.)*m.b*(fm*.5+.04);
  gl_FragColor=vec4(clamp(c,0.,1.)*a,a);
}`;
  const sh=(k,s)=>{const o=gl.createShader(k);gl.shaderSource(o,s);gl.compileShader(o);if(!gl.getShaderParameter(o,gl.COMPILE_STATUS))console.error('Hero water:',gl.getShaderInfoLog(o));return o};
  const pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,VS));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,FS));gl.linkProgram(pr);
  if(!gl.getProgramParameter(pr,gl.LINK_STATUS)) return;
  gl.useProgram(pr);
  gl.bindBuffer(gl.ARRAY_BUFFER,gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);
  const loc=gl.getAttribLocation(pr,'p');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
  const ut=gl.getUniformLocation(pr,'t');
  // keep the canvas locked to the photo at every size, position and zoom
  function place(){
    const pos=getComputedStyle(img).objectPosition.split(' ').map(x=>parseFloat(x)/100);
    const z=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--hz'))||1;
    const W=img.clientWidth,H=img.clientHeight,s=Math.max(W/IW,H/IH);
    const fx=W*pos[0],fy=H*pos[1];
    const ox=fx+((W-IW*s)*pos[0]-fx)*z,oy=fy+((H-IH*s)*pos[1]-fy)*z,k=s*z;
    cv.style.left=ox+X0*k+'px';cv.style.top=oy+Y0*k+'px';cv.style.width=CW*k+'px';cv.style.height=CH*k+'px';
    const w=Math.min(1400,Math.round(CW*k*Math.min(devicePixelRatio||1,2))),h=Math.round(w*CH/CW);
    if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;gl.viewport(0,0,w,h)}
  }
  const load=s=>new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=no;i.src=s});
  Promise.all([load("data:image/webp;base64,"),load("data:image/webp;base64,")]).then(a=>{
    a.forEach((im,i)=>{
      gl.activeTexture(gl.TEXTURE0+i);gl.bindTexture(gl.TEXTURE_2D,gl.createTexture());
      gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,im);
      [gl.TEXTURE_WRAP_S,gl.TEXTURE_WRAP_T].forEach(x=>gl.texParameteri(gl.TEXTURE_2D,x,gl.CLAMP_TO_EDGE));
      gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);
      gl.uniform1i(gl.getUniformLocation(pr,i?'mk':'im'),i);
    });
    img.after(cv);place();
    new ResizeObserver(place).observe(img);
    new MutationObserver(place).observe(document.documentElement,{attributes:true,attributeFilter:['style']});
    let on=false,id=0,last=0;
    function frame(ms){if(ms-last>30){last=ms;gl.uniform1f(ut,(ms/1000)%600);gl.drawArrays(gl.TRIANGLES,0,3)}id=on?requestAnimationFrame(frame):0}
    new IntersectionObserver(e=>{on=e[e.length-1].isIntersecting;if(on&&!id)id=requestAnimationFrame(frame)}).observe(cv);
    cv.addEventListener('webglcontextlost',()=>{on=false;cv.remove()});
    requestAnimationFrame(()=>cv.style.opacity=1);
  }).catch(e=>console.error('Hero water:',e));
})();
